import{_ as t,o,c as i,a2 as a}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0009 — Dettagli implementativi del protocollo di sync (M2)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0009-sync-protocol-details.md","filePath":"adr/0009-sync-protocol-details.md"}'),l={name:"adr/0009-sync-protocol-details.md"};function n(r,e,c,d,s,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0009-—-dettagli-implementativi-del-protocollo-di-sync-m2" tabindex="-1">ADR-0009 — Dettagli implementativi del protocollo di sync (M2) <a class="header-anchor" href="#adr-0009-—-dettagli-implementativi-del-protocollo-di-sync-m2" aria-label="Permalink to &quot;ADR-0009 — Dettagli implementativi del protocollo di sync (M2)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.6.1, §3.1, §3.2.2, §3.4.3, §3.4.4, §3.5.2, §3.5.3 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-24</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§3.2.2 (schema DB), §3.5 (API), §3.6 (protocollo di sync), §3.8 (E2EE), D-02/D-03</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, in modo additivo (campi, colonne e codice di errore aggiuntivi)</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>L&#39;implementazione di M2 ha richiesto alcune scelte non coperte dallo spec o puntualmente diverse. Sono elencate qui per essere recepite o contestate.</p><h2 id="decisioni" tabindex="-1">Decisioni <a class="header-anchor" href="#decisioni" aria-label="Permalink to &quot;Decisioni&quot;">​</a></h2><ol><li><strong><code>op_id</code> su <code>file_revisions</code></strong> (unico per vault): garantisce l&#39;idempotenza dei commit ripetuti dopo un timeout (già previsto dalla roadmap, M2-WP2).</li><li><strong><code>path_key</code> in <code>CommitOp</code></strong> per i vault privati: il server non vede i path; la collisione si verifica su <code>hmac1:&lt;hex&gt;</code> mentre il path opaco <code>enc1:&lt;b64url&gt;</code> è solo archiviato.</li><li><strong>Codice <code>NAME_IN_USE</code> (409)</strong> quando l&#39;utente crea un vault con un nome già usato tra i propri vault attivi (indice univoco parziale).</li><li><strong>Tabella <code>vault_blobs</code></strong> (capability per vault, <code>ON DELETE CASCADE</code>): un blob content-addressed globale è leggibile solo da chi ne ha la capability nel vault; la dedup verifica anche che l&#39;oggetto esista nello store.</li><li><strong>Commit a transazione unica per batch (fast path)</strong>, con fallback a una transazione per op in caso di race (violazione unique, deadlock, flush quota). Contatori di quota e <code>ref_count</code> accumulati per batch e applicati una sola volta in ordine di hash. Un&#39;alternativa con SAVEPOINT per op è stata scartata per le prestazioni (&gt;64 sotto-transazioni).</li><li><strong>tus fuori da OpenAPI</strong>: gestito da un handler dedicato (<code>/vaults/{vid}/uploads</code>); i chunk sono oggetti separati nello store e vengono assemblati in finalizzazione con verifica SHA-256 (compatibile con S3 senza multipart server-side).</li><li><strong>SSE <code>/events</code></strong> usa <code>?known=&lt;vault:seq,...&gt;</code> invece di <code>Last-Event-ID</code> (gli eventi sono per più vault); il hub raggruppa (coalescing) gli eventi per vault.</li><li><strong><code>sync.db</code> per vault</strong> senza colonna <code>vault_id</code> (un DB per vault locale); colonna <code>base_rev</code> distinta da <code>server_rev</code> per l&#39;antenato del merge 3-way.</li><li><strong>Serializzazione per vault</strong>: scritture concorrenti sullo stesso vault sono serializzate dal lock del vault (p95 ≈ 1,15 s con 8 scrittori sullo stesso vault; informativo, il criterio di uscita riguarda scrittori su vault distinti).</li></ol><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Migrazione <code>0003_vaults.sql</code> (la <code>0002</code> è già occupata dal seed delle impostazioni di M0, quindi il numero previsto dalla roadmap per M2 slitta di uno).</li><li><code>api/openapi.yaml</code> v1.0.0-m2 contiene <code>path_key</code>, <code>NAME_IN_USE</code> e la risposta <code>Conflict</code>.</li><li>Limite noto: ricerca su 50k note oltre il budget (tracciato da M1, non risolto da M2).</li></ul>',8)])])}const v=t(l,[["render",n]]);export{g as __pageData,v as default};
